"""Knuth–Bendix completion with proofs, for identities in a finite group generated by
two-wire gates (CliffCS₂ on two wires).

Words are in operator order (as `FreeMonoid.toList` in Lean), letters (gate, wire).  Every
rule lhs -> rhs carries a derivation: a list of steps (pos, rid, rev) rewriting, at position
pos, rule rid (its lhs into its rhs, or back if rev) -- or, for a base rule, the name of the
equation it orients.  Completion runs until given target equations reduce to the same normal
form; the rules their proofs use are exported in the format of the driver's results."""
import heapq, time

class KB:
    def __init__(self, letters, base):
        """letters: the alphabet in increasing order (shortlex); base: (name, lhs, rhs) with
        lhs, rhs operator-order letter tuples, each an equation proved elsewhere."""
        self.letters = list(letters)
        self.code = {a: bytes([i]) for i, a in enumerate(self.letters)}
        self.rules = []          # rid -> [lhs, rhs, proof, alive]
        self.index = {}          # lhs bytes -> rid
        self.lens = set()
        self.pending = []
        self.cnt = 0
        for name, l, r in base:
            self.push(self.enc(l), self.enc(r), ('base', name))

    def enc(self, w): return b''.join(self.code[a] for a in w)
    def dec(self, b): return tuple(self.letters[c] for c in b)

    @staticmethod
    def gt(u, v):
        return len(u) > len(v) or (len(u) == len(v) and u > v)

    # --- reduction
    def reduce(self, w):
        steps = []
        lens = sorted(self.lens)
        i = 0
        while i < len(w):
            done = False
            for L in lens:
                if i + L > len(w): break
                rid = self.index.get(w[i:i + L])
                if rid is not None:
                    lhs, rhs = self.rules[rid][0], self.rules[rid][1]
                    w = w[:i] + rhs + w[i + L:]
                    steps.append((i, rid, False))
                    i = max(0, i - max(lens))
                    done = True
                    break
            if not done: i += 1
        return w, steps

    @staticmethod
    def invert(steps):
        return [(p, r, not rev) for (p, r, rev) in reversed(steps)]

    # --- equations
    def push(self, u, v, proof):
        """An equation u = v; proof is ('base', name) or a step list from u to v."""
        self.cnt += 1
        heapq.heappush(self.pending, (max(len(u), len(v)), self.cnt, u, v, proof))

    def add_rule(self, lhs, rhs, proof):
        rid = len(self.rules)
        self.rules.append([lhs, rhs, proof, True])
        self.index[lhs] = rid
        self.lens.add(len(lhs))
        return rid

    def kill(self, rid):
        r = self.rules[rid]
        if not r[3]: return
        r[3] = False
        if self.index.get(r[0]) == rid: del self.index[r[0]]
        self.lens = set(len(k) for k in self.index)

    def process(self, u, v, proof):
        nu, su = self.reduce(u)
        nv, sv = self.reduce(v)
        if nu == nv: return None
        if proof[0] == 'base':
            # a base rule: orient the equation itself first
            if self.gt(u, v): rid0 = self.add_rule(u, v, ('base', proof[1], False))
            else: rid0 = self.add_rule(v, u, ('base', proof[1], True))
            # it may not be reduced: re-push as a derived equation and let it be normalised
            self.kill(rid0)
            st = [(0, rid0, False)]
            l0, r0 = self.rules[rid0][0], self.rules[rid0][1]
            return self.process(l0, r0, st)
        steps = proof
        if self.gt(nu, nv):
            lhs, rhs, st = nu, nv, self.invert(su) + steps + sv
        else:
            lhs, rhs, st = nv, nu, self.invert(sv) + self.invert(steps) + su
        rid = self.add_rule(lhs, rhs, st)
        # interreduce
        for oid in list(self.index.values()):
            if oid == rid: continue
            ol, orr = self.rules[oid][0], self.rules[oid][1]
            if lhs in ol:
                self.kill(oid)
                self.push(ol, orr, [(0, oid, False)])
            elif lhs in orr:
                nr, sr = self.reduce(orr)
                self.kill(oid)
                self.add_rule(ol, nr, [(0, oid, False)] + sr)
        # critical pairs
        for oid in list(self.index.values()):
            self.overlaps(rid, oid)
            if oid != rid: self.overlaps(oid, rid)
        return rid

    def overlaps(self, a, b):
        A, B = self.rules[a], self.rules[b]
        if not (A[3] and B[3]): return
        la, lb = A[0], B[0]
        for k in range(1, min(len(la), len(lb))):
            if la[-k:] == lb[:k]:
                u1 = A[1] + lb[k:]
                u2 = la[:-k] + B[1]
                self.push(u1, u2, [(0, a, True), (len(la) - k, b, False)])

    def run(self, targets=None, maxrules=100000, report=2000, maxlen=None):
        t0 = time.time()
        n = 0
        while self.pending:
            m, _, u, v, proof = heapq.heappop(self.pending)
            if maxlen and m > maxlen: continue
            self.process(u, v, proof)
            n += 1
            if n % report == 0:
                print('  kb: %d processed, %d rules, %d pending, %.0fs' % (
                    n, len(self.index), len(self.pending), time.time() - t0), flush=True)
                if targets and all(self.provable(l, r) for l, r in targets): return True
            if len(self.index) > maxrules: return False
        return True

    def provable(self, l, r):
        return self.reduce(self.enc(l))[0] == self.reduce(self.enc(r))[0]

    def proof_of(self, l, r):
        """Steps from l to r (operator-order letter tuples), or None."""
        nl, sl = self.reduce(self.enc(l))
        nr, sr = self.reduce(self.enc(r))
        if nl != nr: return None
        return sl + self.invert(sr)

    def replay(self, w, steps):
        w = self.enc(w) if not isinstance(w, bytes) else w
        for (p, rid, rev) in steps:
            lhs, rhs = self.rules[rid][0], self.rules[rid][1]
            a, b = (rhs, lhs) if rev else (lhs, rhs)
            assert w[p:p + len(a)] == a, (p, rid, rev)
            w = w[:p] + b + w[p + len(a):]
        return w

    def check(self, rid):
        lhs, rhs, proof, _ = self.rules[rid]
        if proof[0] == 'base': return True
        return self.replay(lhs, proof) == rhs
